/**
 * Shared Paystack form actions for Sales Invoice and Sales Order.
 *
 * Exposes frappe_paystack.actions.setupForm(frm, config).
 */
frappe.provide("frappe_paystack.actions");

(function (actions) {
	"use strict";

	const BUTTON_GROUP = __("Paystack");
	const DEFAULT_CURRENCY = "NGN";

	function currencyOf(frm) {
		return frm.doc.currency || DEFAULT_CURRENCY;
	}

	function formatMoney(amount, currency) {
		return format_currency(flt(amount), currency);
	}

	/** Resolve the customer's email, or show a message and resolve to null. */
	function fetchCustomerEmail(frm) {
		return frappe
			.call("frappe_paystack.utils.get_customer_email", {
				customer: frm.doc.customer,
			})
			.then((res) => {
				if (!res.message) {
					frappe.msgprint({
						title: __("Email required"),
						message: __("Set an Email ID on customer {0} first.", [
							frm.doc.customer,
						]),
						indicator: "orange",
					});
					return null;
				}
				return res.message;
			});
	}

	function createPaymentLink(frm, amount) {
		return frappe
			.call({
				method: "frappe_paystack.api.create_payment_link",
				args: {
					doctype: frm.doc.doctype,
					docname: frm.doc.name,
					amount: flt(amount),
					currency: currencyOf(frm),
				},
				freeze: true,
				freeze_message: __("Generating payment link..."),
			})
			.then((res) => {
				if (!res.message) {
					frappe.msgprint({
						title: __("Could not create link"),
						message: __("Paystack did not return a payment link."),
						indicator: "red",
					});
					return null;
				}
				return res.message;
			});
	}

	/** The Payment Log name a checkout URL ends with. */
	function referenceOf(url) {
		return String(url).replace(/\/+$/, "").split("/").pop();
	}

	/** Fetch the checkout QR code and show it inside an open dialog. */
	function renderQrCode(dialog, url) {
		return frappe
			.call({
				method: "frappe_paystack.api.payment_link_qr",
				args: { reference: referenceOf(url) },
			})
			.then((res) => {
				if (!res.message) {
					return;
				}
				// The source is a data URI generated by this app.
				dialog.fields_dict.qr.$wrapper.html(
					`<img src="${res.message}" alt="${__(
						"Payment link QR code"
					)}" style="width: 160px; height: 160px;">`
				);
			});
	}

	function showLinkDialog(url) {
		const dialog = new frappe.ui.Dialog({
			title: __("Paystack payment link"),
			fields: [
				{
					fieldtype: "Data",
					fieldname: "link",
					label: __("Payment Link"),
					read_only: 1,
					default: url,
				},
				{
					fieldtype: "HTML",
					fieldname: "qr",
				},
				{
					fieldtype: "HTML",
					fieldname: "hint",
					options: `<p class="text-muted small">${__(
						"Share this link with your customer to collect payment."
					)}</p>`,
				},
			],
			primary_action_label: __("Open"),
			primary_action() {
				window.open(url, "_blank", "noopener");
				dialog.hide();
			},
			secondary_action_label: __("Copy"),
			secondary_action() {
				copyToClipboard(url);
			},
		});

		dialog.show();
		renderQrCode(dialog, url);
	}

	function copyToClipboard(text) {
		if (navigator.clipboard && navigator.clipboard.writeText) {
			navigator.clipboard
				.writeText(text)
				.then(() =>
					frappe.show_alert({ message: __("Link copied"), indicator: "green" })
				)
				.catch(() => frappe.msgprint(__("Copy this link:") + "<br>" + text));
			return;
		}
		frappe.msgprint(__("Copy this link:") + "<br>" + text);
	}

	function showEmailDialog(frm, url, email) {
		const dialog = new frappe.ui.Dialog({
			title: __("Send payment link"),
			fields: [
				{
					fieldtype: "Data",
					fieldname: "recipient",
					label: __("To"),
					options: "Email",
					reqd: 1,
					default: email,
				},
				{
					fieldtype: "Data",
					fieldname: "subject",
					label: __("Subject"),
					reqd: 1,
					default: __("Payment link for {0}", [frm.doc.name]),
				},
				{
					fieldtype: "Text Editor",
					fieldname: "message",
					label: __("Message"),
					default: buildEmailBody(frm, url),
				},
			],
			primary_action_label: __("Send"),
			primary_action(values) {
				frappe
					.call({
						method: "frappe.core.doctype.communication.email.make",
						args: {
							recipients: values.recipient,
							subject: values.subject,
							content: values.message,
							doctype: frm.doc.doctype,
							name: frm.doc.name,
							send_email: 1,
						},
						freeze: true,
						freeze_message: __("Sending..."),
					})
					.then(() => {
						dialog.hide();
						frappe.show_alert({
							message: __("Payment link sent to {0}", [values.recipient]),
							indicator: "green",
						});
					});
			},
		});

		dialog.show();
	}

	function buildEmailBody(frm, url) {
		const safeUrl = frappe.utils.escape_html(url);
		return [
			`<p>${__("Hello,")}</p>`,
			`<p>${__("Please use the secure link below to complete your payment for {0}.", [
				frappe.utils.escape_html(frm.doc.name),
			])}</p>`,
			`<p><a href="${safeUrl}">${safeUrl}</a></p>`,
			`<p>${__("Thank you.")}</p>`,
		].join("");
	}

	/** Generate a link and either open it or offer to email it. */
	function collectPayment(frm, amount, options) {
		const settings = options || {};

		if (flt(amount) <= 0) {
			frappe.msgprint({
				title: __("Nothing to pay"),
				message: __("There is no outstanding amount on this document."),
				indicator: "orange",
			});
			return;
		}

		if (!settings.send) {
			createPaymentLink(frm, amount).then((url) => url && showLinkDialog(url));
			return;
		}

		fetchCustomerEmail(frm).then((email) => {
			if (!email) {
				return;
			}
			createPaymentLink(frm, amount).then(
				(url) => url && showEmailDialog(frm, url, email)
			);
		});
	}

	/** Return true and show a message when the amount falls outside (0, outstanding]. */
	function rejectsAmount(amount, outstanding, currency) {
		if (amount > 0 && amount <= flt(outstanding)) {
			return false;
		}

		frappe.msgprint({
			title: __("Invalid amount"),
			message: __("Enter an amount between {0} and {1}.", [
				formatMoney(0.01, currency),
				formatMoney(outstanding, currency),
			]),
			indicator: "red",
		});
		return true;
	}

	/** Show the customer's stored cards, or a message when there are none. */
	function chargeSavedCard(frm, outstanding) {
		return frappe
			.call({
				method: "frappe_paystack.api.saved_cards",
				args: { customer: frm.doc.customer, company: frm.doc.company },
			})
			.then((res) => {
				const cards = res.message || [];
				if (!cards.length) {
					frappe.msgprint({
						title: __("No saved cards"),
						message: __(
							"{0} has no saved card. Paystack stores one the first time they pay a card online.",
							[frm.doc.customer]
						),
						indicator: "orange",
					});
					return;
				}
				showSavedCardDialog(frm, cards, outstanding);
			});
	}

	function showSavedCardDialog(frm, cards, outstanding) {
		const currency = currencyOf(frm);

		const dialog = new frappe.ui.Dialog({
			title: __("Charge a saved card"),
			fields: [
				{
					fieldtype: "Select",
					fieldname: "card",
					label: __("Card"),
					reqd: 1,
					default: cards[0].name,
					options: cards.map((card) => ({
						label: card.card_label || card.name,
						value: card.name,
					})),
				},
				{
					fieldtype: "Currency",
					fieldname: "amount",
					label: __("Amount"),
					options: "currency",
					reqd: 1,
					default: outstanding,
					description: __("Outstanding: {0}", [
						formatMoney(outstanding, currency),
					]),
				},
				{
					fieldtype: "Data",
					fieldname: "currency",
					hidden: 1,
					default: currency,
				},
			],
			primary_action_label: __("Charge"),
			primary_action(values) {
				const amount = flt(values.amount);
				if (rejectsAmount(amount, outstanding, currency)) {
					return;
				}

				dialog.hide();
				frappe
					.call({
						method: "frappe_paystack.api.charge_saved_card",
						args: {
							doctype: frm.doc.doctype,
							docname: frm.doc.name,
							authorization: values.card,
							amount: amount,
						},
						freeze: true,
						freeze_message: __("Charging the saved card..."),
					})
					.then((res) => {
						if (!res.message) {
							return;
						}
						frappe.show_alert({
							message: __("Card charged. Payment {0} is settling.", [
								res.message,
							]),
							indicator: "green",
						});
					});
			},
		});

		dialog.show();
	}

	function showPartialDialog(frm, outstanding) {
		const currency = currencyOf(frm);

		const dialog = new frappe.ui.Dialog({
			title: __("Partial payment"),
			fields: [
				{
					fieldtype: "Currency",
					fieldname: "amount",
					label: __("Amount"),
					options: "currency",
					reqd: 1,
					default: outstanding,
					description: __("Outstanding: {0}", [
						formatMoney(outstanding, currency),
					]),
				},
				{
					fieldtype: "Data",
					fieldname: "currency",
					hidden: 1,
					default: currency,
				},
				{
					fieldtype: "Select",
					fieldname: "mode",
					label: __("Then"),
					reqd: 1,
					default: "Open link",
					options: [__("Open link"), __("Email link")].join("\n"),
				},
			],
			primary_action_label: __("Continue"),
			primary_action(values) {
				const amount = flt(values.amount);

				if (rejectsAmount(amount, outstanding, currency)) {
					return;
				}

				dialog.hide();
				collectPayment(frm, amount, { send: values.mode === __("Email link") });
			},
		});

		dialog.show();
	}

	/**
	 * Add the Paystack button group to a form.
	 *
	 * config.getOutstanding(frm) must return the payable amount, and
	 * config.isPayable(frm) whether the document may still be paid.
	 */
	actions.setupForm = function setupForm(frm, config) {
		if (!frm.doc.company || frm.doc.docstatus !== 1) {
			return;
		}

		if (!config.isPayable(frm)) {
			return;
		}

		const outstanding = flt(config.getOutstanding(frm));
		if (outstanding <= 0) {
			return;
		}

		frappe
			.call({
				method: "frappe_paystack.api.is_enabled_for_company",
				args: { company: frm.doc.company },
			})
			.then((res) => {
				if (!res.message) {
					return;
				}

				frm.add_custom_button(
					__("Pay now"),
					() => collectPayment(frm, outstanding),
					BUTTON_GROUP
				);

				frm.add_custom_button(
					__("Email payment link"),
					() => collectPayment(frm, outstanding, { send: true }),
					BUTTON_GROUP
				);

				frm.add_custom_button(
					__("Partial payment"),
					() => showPartialDialog(frm, outstanding),
					BUTTON_GROUP
				);

				frm.add_custom_button(
					__("Charge saved card"),
					() => chargeSavedCard(frm, outstanding),
					BUTTON_GROUP
				);
			});
	};
})(frappe_paystack.actions);
